        public void formatting(Control control)
        {
            var controls = control.Controls.Cast<Control>();
            foreach (Control item in controls)
            {
                if (item.DataBindings.Count > 0)
                {
                    item.DataBindings[0].Format += new ConvertEventHandler(coffee.DecimalToCurrencyString);
                    item.DataBindings[0].Parse += new ConvertEventHandler(coffee.CurrencyStringToDecimal);
                }
            }

        }

